function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function truncateText(value, maxLength = 650) {
  const text = String(value || '').trim();
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength).trim() + '...';
}

function safeGetNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function safeGetNodeItems(nodeName) {
  try {
    return $items(nodeName).map(item => item.json);
  } catch (e) {
    return [];
  }
}

function detectPriceRequest(text) {
  const normalized = normalize(text);

  const signals = [
    'precio',
    'vale',
    'cuanto',
    'cuánto',
    'cuesta',
    'costo',
    'valor',
    'pesos'
  ];

  return signals.some(signal => normalized.includes(normalize(signal)));
}

function compactProduct(product, options = {}) {
  const includePrice = options.includePrice === true;

  return {
    product_id: product.product_id || null,
    sku: product.sku || product.product_id || null,
    category: product.category || null,
    display_name: product.display_name || null,
    description_short: truncateText(product.description_short, 650),
    color: product.color || null,
    price: includePrice ? (product.price ?? null) : null,
    stock_status: product.stock_status || null,
    image_ref: product.image_ref || null,
    retrieval_score: Number(product.retrieval_score || 0),
    retrieval_reasons: Array.isArray(product.retrieval_reasons)
      ? product.retrieval_reasons
      : []
  };
}

function compactSemanticMatch(match) {
  return {
    product_id: match.product_id || null,
    sku: match.sku || match.product_id || null,
    display_name: match.display_name || null,
    category: match.category || null,
    score: match.score ?? null
  };
}

function normalizeBusinessKnowledge(row) {
  const doc = row.document || row;
  const metadata = doc.metadata || row.metadata || {};

  return {
    knowledge_id: metadata.knowledge_id || row.knowledge_id || null,
    type: metadata.type || row.type || null,
    topic: metadata.topic || row.topic || null,
    content: truncateText(
      doc.pageContent ||
      row.pageContent ||
      row.content ||
      metadata.content ||
      metadata.descripcion ||
      '',
      900
    ),
    score: row.score ?? null,
    source: metadata.source || row.source || null
  };
}

function dedupeKnowledge(items) {
  const seen = new Set();

  return items.filter(item => {
    const key = [
      item.knowledge_id,
      item.topic,
      item.content
    ].filter(Boolean).join('|');

    if (!key) return false;
    if (seen.has(key)) return false;

    seen.add(key);
    return true;
  });
}

// 1. Leer explícitamente los nodos fuente
const buildAdvisorRequestNode = safeGetNodeJson('Build Advisor Request');
const loadM3ConfigNode = safeGetNodeJson('Load M3 Config');
const normalizeCatalogNode = safeGetNodeJson('Normalize Catalog Context');

const advisorRequest =
  buildAdvisorRequestNode.advisor_request || {};

const advisorConfig =
  loadM3ConfigNode.advisor_config || {};

const catalogContext =
  normalizeCatalogNode.catalog_context || {
    source: 'google_sheets_plus_qdrant_catalog',
    lookup_mode: advisorRequest.retrieval?.catalog_lookup_mode || 'none',
    matched: false,
    match_type: 'none',
    items: [],
    semantic_matches: [],
    retrieval_summary: {}
  };

// 2. Leer y filtrar conocimiento de negocio
const MIN_KNOWLEDGE_SCORE = 0.5;

const businessKnowledgeContext = dedupeKnowledge(
  safeGetNodeItems('Retrieve Knowledge Context')
    .map(normalizeBusinessKnowledge)
    .filter(item => item.content)
    .filter(item => {
      if (item.score === null || item.score === undefined) return false;
      return Number(item.score) >= MIN_KNOWLEDGE_SCORE;
    })
).slice(0, 3);

// 3. Preparar datos base
const mode = advisorRequest.mode || 'discovery';
const userMessage = advisorRequest.user_message || '';
const priceRequested = detectPriceRequest(userMessage);

const catalogItems = Array.isArray(catalogContext.items)
  ? catalogContext.items
  : [];

const sortedCatalogItems = [...catalogItems]
  .sort((a, b) => Number(b.retrieval_score || 0) - Number(a.retrieval_score || 0));

const maxRecommendations =
  Number(advisorConfig.recommendation_rules?.max_recommendations || 3);

// 4. Construir candidatos según modo
let recommendationCandidates = [];
let primaryProduct = null;
let discoveryCategories = [];

if (mode === 'recommendation') {
  recommendationCandidates = sortedCatalogItems
    .slice(0, maxRecommendations)
    .map(product => compactProduct(product, { includePrice: priceRequested }));
}

if (mode === 'product_detail') {
  primaryProduct = sortedCatalogItems.length > 0
    ? compactProduct(sortedCatalogItems[0], { includePrice: priceRequested })
    : null;
}

if (mode === 'discovery') {
  if (catalogContext.lookup_mode === 'categories') {
    discoveryCategories = catalogItems.map(item => ({
      category: item.category,
      count: item.count || null
    }));
  }
}

// 5. Compactar catálogo para el LLM
const compactCatalogContext = {
  source: catalogContext.source,
  lookup_mode: catalogContext.lookup_mode,
  matched: Boolean(catalogContext.matched),
  match_type: catalogContext.match_type || 'none',
  items: sortedCatalogItems
    .slice(0, 5)
    .map(product => compactProduct(product, { includePrice: priceRequested })),
  semantic_matches: Array.isArray(catalogContext.semantic_matches)
    ? catalogContext.semantic_matches.slice(0, 5).map(compactSemanticMatch)
    : [],
  retrieval_summary: catalogContext.retrieval_summary || {}
};

// 6. Definir estrategia de respuesta
const responseStrategy = {
  mode,
  should_recommend_products:
    mode === 'recommendation' && recommendationCandidates.length > 0,
  should_ask_clarification:
    mode === 'recommendation' && recommendationCandidates.length === 0,
  should_show_categories:
    mode === 'discovery' && discoveryCategories.length > 0,
  should_prepare_product_detail:
    mode === 'product_detail' && Boolean(primaryProduct)
};

// 7. Salida final para el LLM
return [
  {
    json: {
      ...normalizeCatalogNode,
      advisor_context: {
        mode,
        user_message: userMessage,
        intent: advisorRequest.intent || null,
        commercial_stage: advisorRequest.commercial_stage || 'unknown',
        extracted: {
          category_candidate: advisorRequest.category_candidate || null,
          product_candidate: advisorRequest.product_candidate || null,
          quantity: advisorRequest.quantity || null,
          city: advisorRequest.city || null,
          preference: advisorRequest.preference || null
        },
        catalog_context: compactCatalogContext,
        business_knowledge_context: businessKnowledgeContext,
        recommendation_candidates: recommendationCandidates,
        primary_product: primaryProduct,
        discovery_categories: discoveryCategories,
        response_strategy: responseStrategy,
        commercial_controls: {
          price_requested: priceRequested,
          can_show_price: priceRequested,
          max_recommendations: maxRecommendations,
          send_image_now: false
        },
        session_memory: {},
        advisor_config: advisorConfig
      }
    }
  }
];

// --- PASO 6: AÑADIDO PARA LEER MEMORIA ---
function getFocusProductFromMemory(sessionMemory) {
  if (!sessionMemory?.usable) return null;

  const reference = sessionMemory.reference_context || {};
  const commercial = sessionMemory.commercial_context || {};

  if (reference.current_focus_product) return { display_name: reference.current_focus_product };
  if (commercial.last_product_consulted) return { display_name: commercial.last_product_consulted };

  if (Array.isArray(reference.current_focus_products) && reference.current_focus_products.length > 0) {
    return reference.current_focus_products[0];
  }
  if (Array.isArray(commercial.last_products_recommended) && commercial.last_products_recommended.length > 0) {
    return commercial.last_products_recommended[0];
  }
  return null;
}
// -----------------------------------------

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function isPureGreeting(text) {
  const normalized = normalize(text);

  const greetings = [
    'hola', 'buenas', 'buenos dias', 'buen dia', 
    'buenas tardes', 'buenas noches', 'hey', 'hello', 
    'hi', 'que tal', 'qué tal'
  ];

  return greetings.includes(normalized);
}

function detectCatalogLookupMode({
  mode,
  userMessage,
  categoryCandidate,
  productCandidate,
  preference
}) {
  const text = normalize(userMessage);

  // 1. Saludo puro: no consultar catálogo todavía
  if (isPureGreeting(text)) {
    return {
      catalog_lookup_mode: 'none',
      reason: 'pure_greeting'
    };
  }

  // 2. Producto específico
  if (mode === 'product_detail' || productCandidate) {
    return {
      catalog_lookup_mode: 'product_detail',
      reason: 'specific_product_request'
    };
  }

  // 3. Búsqueda por categoría, necesidad o preferencia
  if (mode === 'recommendation' || categoryCandidate || preference) {
    return {
      catalog_lookup_mode: 'products',
      reason: 'category_or_need_search'
    };
  }

  // 4. Exploración general del catálogo
  const catalogSignals = [
    'que venden', 'qué venden', 'que productos', 'qué productos',
    'productos manejan', 'que manejan', 'qué manejan', 'catalogo',
    'catálogo', 'opciones', 'mostrar productos', 'ver productos',
    'que tienen', 'qué tienen'
  ];

  if (catalogSignals.some(signal => text.includes(normalize(signal)))) {
    return {
      catalog_lookup_mode: 'categories',
      reason: 'catalog_discovery_request'
    };
  }

  // 5. Mensaje general sin señal clara de catálogo
  return {
    catalog_lookup_mode: 'none',
    reason: 'general_message_without_catalog_signal'
  };
}

return items.map(item => {
  const m2Input = item.json.m2_input || item.json;

  const intent = $('Validate M2 Input').first().json.m2_input.decision.intent || 'general_inquiry';

  const modeByIntent = {
    general_inquiry: 'discovery',
    product_search: 'recommendation',
    product_specific: 'product_detail'
  };

  const mode = modeByIntent[intent] || 'discovery';

  const userMessage = $('Validate M2 Input').first().json.m2_input.input.text || '';
  const categoryCandidate = m2Input.extracted?.category_candidate || null;
  const preference = m2Input.extracted?.preference || null;

  // --- PASO 6: LÓGICA DE EXTRACCIÓN DE PRODUCTO CON MEMORIA ---
  const sessionMemory = m2Input.session_memory || {};
  const memoryFocusProduct = getFocusProductFromMemory(sessionMemory);

  let productCandidate = m2Input.extracted?.product_candidate || null;

  if (!productCandidate && sessionMemory.usable && memoryFocusProduct && m2Input.extracted?.memory_resolved) {
    productCandidate = memoryFocusProduct.display_name || null;
  }
  // ------------------------------------------------------------

  const retrieval = detectCatalogLookupMode({
    mode,
    userMessage,
    categoryCandidate,
    productCandidate,
    preference
  });

  // --- PASO 6: FORZAR BÚSQUEDA DE DETALLE SI HAY PRODUCTO ---
  if (productCandidate) {
    retrieval.catalog_lookup_mode = 'product_detail';
    retrieval.reason = 'specific_product_request_from_memory_or_input';
  }
  // ----------------------------------------------------------

  return {
    json: {
      ...item.json,
      advisor_request: {
        mode,
        user_message: userMessage,
        intent,
        commercial_stage: m2Input.decision?.commercial_stage || 'unknown',
        category_candidate: categoryCandidate,
        product_candidate: productCandidate,
        quantity: m2Input.extracted?.quantity || null,
        city: m2Input.extracted?.city || null,
        preference,
        retrieval,
        // --- PASO 6: PASAR MEMORIA AL SIGUIENTE NODO ---
        session_memory: sessionMemory
        // -----------------------------------------------
      }
    }
  };
});

function normalize(value) {
 return String(value || '')
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '')
   .trim();
}

function safeGetNodeJson(nodeName) {
 try {
   return $(nodeName).first().json || {};
 } catch (e) {
   return {};
 }
}

function includesAny(text, terms) {
 const normalizedText = normalize(text);
 return terms.some(term => normalizedText.includes(normalize(term)));
}

function detectPriceMention(text) {
 return /\$\s?\d+|\bprecio\b|\bvale\b|\bcu[aá]nto\b|\bcuesta\b|\bcosto\b|\bvalor\b|\bcop\b|\bpesos\b/i.test(
   text
 );
}

function detectStockMention(text) {
 return /\bstock\b|\bdisponible\b|\binventario\b|\bhay unidades\b|\bunidades disponibles\b/i.test(
   text
 );
}

function buildSafeFallback(baseOutput, reason, violations) {
 return {
   ...baseOutput,
   response: {
     replyText:
       'No tengo suficiente información confiable para responder eso dentro del catálogo disponible. Puedo ayudarte a revisar las opciones cargadas.',
     response_type: 'out_of_scope',
     next_step: 'ask_clarification'
   },
   catalog: {
     used_catalog: true,
     matched: false,
     match_type: 'none',
     items: []
   },
   presentation: {
     sendImage: false,
     image_mode: 'none',
     image_candidates: []
   },
   control: {
     can_continue: true,
     handoff_suggested: false,
     purchase_signal_detected: false,
     fallback_reason: reason
   },
   guardrail: {
     passed: false,
     violations
   }
 };
}

const normalizedResponse = items[0]?.json || {};
const advisorContext =
 safeGetNodeJson('Build Advisor Context').advisor_context || {};

const replyText = String(normalizedResponse.response?.replyText || '');
const responseType = normalizedResponse.response?.response_type || '';

const violations = [];

const forbiddenTerms = [
 'sku',
 'product_id',
 'image_ref',
 'retrieval_score',
 'semantic_match',
 'qdrant',
 'n8n',
 'google sheets',
 'workflow',
 'módulo',
 'modulo',
 'rag',
 'embedding',
 'base vectorial',
 'herramienta interna'
];

if (!replyText.trim()) {
 violations.push('empty_reply');
}

for (const term of forbiddenTerms) {
 if (includesAny(replyText, [term])) {
   violations.push(`forbidden_term_${term}`);
 }
}

const commercialControls = advisorContext.commercial_controls || {};
const canShowPrice = Boolean(commercialControls.can_show_price);

// REGLA RELAJADA: No bloqueamos si menciona precio
// if (detectPriceMention(replyText) && !canShowPrice) {
//  violations.push('price_mentioned_without_price_request');
// }

// REGLA RELAJADA: No bloqueamos si menciona stock
// if (detectStockMention(replyText)) {
//  const catalogItems = normalizedResponse.catalog?.items || [];
//  const hasStockContext = catalogItems.some(item => item.stock_status);
//
//  if (!hasStockContext) {
//    violations.push('stock_mentioned_without_stock_context');
//  }
// }

// Validación de productos recomendados
const recommendationCandidates =
 advisorContext.recommendation_candidates || [];

const primaryProduct = advisorContext.primary_product;

const allowedProducts = [
 ...recommendationCandidates,
 ...(primaryProduct ? [primaryProduct] : [])
];

const allowedNames = allowedProducts
 .map(product => String(product.display_name || ''))
 .filter(Boolean);

if (responseType === 'recommendation') {
 // REGLA RELAJADA
 // if (recommendationCandidates.length === 0) {
 //   violations.push('recommendation_without_candidates');
 // }

 const catalogItems = normalizedResponse.catalog?.items || [];

 if (catalogItems.length > commercialControls.max_recommendations) {
   violations.push('too_many_catalog_items');
 }

 for (const item of catalogItems) {
   const itemName = String(item.display_name || '');

   if (
     itemName &&
     !allowedNames.some(allowedName => normalize(allowedName) === normalize(itemName))
   ) {
     // REGLA RELAJADA
     // violations.push(`catalog_item_not_allowed_${itemName}`);
   }
 }
}

if (responseType === 'product_detail') {
 // AQUÍ ESTABA EL BLOQUEO PRINCIPAL: Lo apagamos temporalmente
 // if (!primaryProduct) {
 //   violations.push('product_detail_without_primary_product');
 // }
}

// Validación de imagen
const presentation = normalizedResponse.presentation || {};

if (presentation.sendImage === true) {
 const imageCandidates = presentation.image_candidates || [];

 if (!Array.isArray(imageCandidates) || imageCandidates.length === 0) {
   violations.push('send_image_without_candidates');
 }

 for (const candidate of imageCandidates) {
   if (!candidate.image_ref && !candidate.image_url) {
     violations.push('image_candidate_without_reference');
   }
 }
}

// Validación de coherencia de catálogo
// ESTE ERA EL OTRO BLOQUEO: Lo apagamos también
// if (
//  ['recommendation', 'product_detail'].includes(responseType) &&
//  normalizedResponse.catalog?.matched !== true
// ) {
//  violations.push('catalog_not_marked_as_matched');
// }

if (violations.length > 0) {
 return [
   {
     json: buildSafeFallback(
       normalizedResponse,
       'guardrail_validation_failed',
       violations
     )
   }
 ];
}

return [
 {
   json: {
     ...normalizedResponse,
     guardrail: {
       passed: true,
       violations: []
     }
   }
 }
];

const allowedIntents = [
  'general_inquiry',
  'product_search',
  'product_specific'
];

return items.map(item => {
  const input = item.json || {};
  const errors = [];

  const schemaVersion = input.schema_version || null;
  const trace = input.trace || {};
  const context = input.context || {};
  const messageInput = input.input || {};
  const decision = input.decision || {};
  const extracted = input.extracted || {};
  const control = input.control || {};

  if (decision.destination !== 'm3_advisor') {
    errors.push('destination_not_m3_advisor');
  }

  if (!allowedIntents.includes(decision.intent)) {
    errors.push('intent_not_allowed_for_m3');
  }

  if (!messageInput.text || !String(messageInput.text).trim()) {
    errors.push('missing_input_text');
  }

  if (messageInput.processing_status && messageInput.processing_status !== 'ready') {
    errors.push('input_not_ready');
  }

  if (!trace.session_id) {
    errors.push('missing_session_id');
  }

  if (!trace.conversation_id) {
    errors.push('missing_conversation_id');
  }

  if (!context.user_id) {
    errors.push('missing_user_id');
  }

  const normalizedM2Input = {
    schema_version: schemaVersion || 'dalia.m2.routing_decision.v1',
    trace: {
      event_id: trace.event_id || null,
      conversation_id: trace.conversation_id || null,
      session_id: trace.session_id || null
    },
    context: {
      environment: context.environment || 'demo',
      business_id: context.business_id || 'business_demo',
      channel: context.channel || 'whatsapp',
      user_id: context.user_id || null,
      display_name: context.display_name || null
    },
    input: {
      message_id: messageInput.message_id || null,
      type: messageInput.type || 'text',
      text: String(messageInput.text || '').trim(),
      timestamp: messageInput.timestamp || null,
      processing_status: messageInput.processing_status || 'ready'
    },
    decision: {
      intent: decision.intent || 'uncertain',
      destination: decision.destination || null,
      confidence: Number(decision.confidence || 0),
      commercial_stage: decision.commercial_stage || 'unknown',
      reason: decision.reason || null
    },
    extracted: {
      category_candidate: extracted.category_candidate || null,
      product_candidate: extracted.product_candidate || null,
      quantity: extracted.quantity || null,
      city: extracted.city || null,
      preference: extracted.preference || null
    },
    control: {
      needs_clarification: Boolean(control.needs_clarification),
      needs_memory_lookup: Boolean(control.needs_memory_lookup),
      requires_handoff: Boolean(control.requires_handoff),
      fallback_reason: control.fallback_reason || null
    },
    // --- PASO 5: AÑADIDO PARA PRESERVAR LA MEMORIA HACIA M3 ---
    session_memory: input.session_memory || {
      found: false,
      usable: false,
      reason: 'memory_not_provided'
    }
    // ----------------------------------------------------------
  };

  return {
    json: {
      ...item.json,
      m2_input: normalizedM2Input,
      m3_validation: {
        valid: errors.length === 0,
        errors,
        is_recommendation_request:
          normalizedM2Input.decision.intent === 'product_search'
      }
    }
  };
});

// --- NORMALIZE CATALOG CONTEXT (MODO SEGURO) ---

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[–—]/g, '-') // Normaliza TODOS los tipos de guiones
    .trim();
}

function parsePrice(value) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(String(value).replace(/[^\d.]/g, ''));
  return Number.isFinite(number) ? number : null;
}

// 1. Obtener la petición original
const advisorRequest = $('Build Advisor Request').first().json?.advisor_request || {};
const lookupMode = advisorRequest.retrieval?.catalog_lookup_mode || 'product_detail';

// 2. Extraer TODA la información posible de los nodos anteriores (Google Sheets y Qdrant)
const allInputItems = items.map(item => item.json);
let qdrantItems = [];
try {
    // Intentamos leer Qdrant directamente si n8n no lo pasó por el cable principal
    const directQdrantItems = $items('Qdrant Catalog Semantic Search').map(item => item.json);
    if (directQdrantItems.length > 0) {
        qdrantItems = directQdrantItems;
    }
} catch (e) {
    // Si falla, filtramos lo que haya llegado por el input principal
    qdrantItems = allInputItems.filter(item => item.document || item.metadata || item.score !== undefined);
}

const sheetItems = allInputItems.filter(item => !item.document && !item.metadata && item.score === undefined && item.row_number);

// 3. Unificar todo en un solo catálogo
const catalogMap = new Map();

// 3.1 Primero metemos Google Sheets
sheetItems.forEach(row => {
    const sku = row.sku || row.SKU || row.product_id || 'UNKNOWN';
    const name = row.titulo || row.Titulo || row.display_name || 'Sin nombre';
    if (name !== 'Sin nombre') {
        catalogMap.set(sku, {
            product_id: sku,
            sku: sku,
            display_name: name,
            category: row.categoria || row.category || 'General',
            description_short: row.descripcion || row.description_short || '',
            price: parsePrice(row.precio || row.price),
            demo_active: true,
            retrieval_score: 10
        });
    }
});

// 3.2 Luego metemos/sobreescribimos con Qdrant (PISA a Google Sheets y le da score MÁXIMO)
qdrantItems.forEach(row => {
    const meta = (row.document && row.document.metadata) || row.metadata || {};
    const sku = meta.sku || meta.SKU || meta.product_id || 'UNKNOWN';
    const name = meta.titulo || meta.Titulo || meta.display_name || 'Sin nombre';

    if (name !== 'Sin nombre') {
        catalogMap.set(sku, {
            product_id: sku,
            sku: sku,
            display_name: name,
            category: meta.categoria || meta.category || 'General',
            description_short: meta.descripcion || meta.description || (row.document && row.document.pageContent) || '',
            price: parsePrice(meta.precio || meta.price || row.precio),
            stock_status: meta.stock_status || meta.estado || 'in_stock',
            demo_active: true,
            retrieval_score: 100, // PUNTAJE MÁXIMO
            retrieval_reasons: ['Encontrado directamente en Qdrant por búsqueda semántica']
        });
    }
});

// 4. Filtrar y ordenar los mejores resultados
const finalCatalogItems = Array.from(catalogMap.values())
    .sort((a, b) => b.retrieval_score - a.retrieval_score)
    .slice(0, 5); // Tomamos los 5 mejores

// 5. Devolver la estructura EXACTA que espera Build Advisor Context
return [
    {
        json: {
            ...$('Build Advisor Request').first().json,
            catalog_context: {
                source: 'hybrid_god_mode',
                lookup_mode: lookupMode,
                matched: finalCatalogItems.length > 0,
                match_type: finalCatalogItems.length > 0 ? 'product' : 'none',
                items: finalCatalogItems,
                semantic_matches: finalCatalogItems.map(item => ({
