function safeParse(value) {
  if (typeof value === 'object' && value !== null) return value;

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (e) {
      const match = value.match(/\{[\s\S]*\}/);
      if (match) {
        try {
          return JSON.parse(match[0]);
        } catch (_) {}
      }
    }
  }

  return {};
}

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function findProductById(productId) {
  const candidates = [
    ...(advisorContext.recommendation_candidates || []),
    ...(advisorContext.catalog_context?.items || []),
    ...(advisorContext.primary_product ? [advisorContext.primary_product] : [])
  ];

  return candidates.find(product =>
    normalize(product.product_id || product.sku) === normalize(productId)
  );
}

function findProductByName(name) {
  const candidates = [
    ...(advisorContext.recommendation_candidates || []),
    ...(advisorContext.catalog_context?.items || []),
    ...(advisorContext.primary_product ? [advisorContext.primary_product] : [])
  ];

  return candidates.find(product =>
    normalize(product.display_name) === normalize(name)
  );
}

