  const source = productFromContext || productFromName || item;

  return {
    product_id: source.product_id || source.sku || item.product_id || null,
    display_name: source.display_name || item.display_name || '',
    category: source.category || item.category || '',
    description_short: source.description_short || item.description_short || '',
    color: source.color || item.color || '',
    price: source.price ?? item.price ?? null,
    stock_status: source.stock_status || item.stock_status || null,
    image_ref: source.image_ref || item.image_ref || null
  };
}

