    return 'Para orientarte mejor, ¿me cuentas qué tipo de producto estás buscando?';
  }

  const first = items[0];
  const second = items[1];
  const third = items[2];

  const firstName = first.display_name || 'esta opción';
  const firstDescription = String(first.description_short || '').trim();

  let benefit = '';

  if (firstDescription) {
    benefit = firstDescription
      .split('.')
      .filter(Boolean)[0]
      .trim();
  }

  if (responseType === 'recommendation') {
    let text = `Para lo que buscas, te recomendaría ${firstName}.`;

    if (benefit) {
      text += ` ${benefit}.`;
    }

    const alternatives = [second, third]
      .filter(Boolean)
      .map(item => item.display_name)
      .filter(Boolean);

    if (alternatives.length > 0) {
      text += ` También puedes revisar ${alternatives.join(' o ')}.`;
    }

    text += ' ¿Quieres que te cuente más detalles de alguna opción?';

    return text;
  }

  if (responseType === 'product_detail') {
    let text = `${firstName} puede ser una buena opción.`;

    if (benefit) {
      text += ` ${benefit}.`;
    }

    text += ' ¿Quieres que te comparta más información?';

    return text;
  }

  return 'Encontré algunas opciones que pueden servirte. ¿Quieres que te muestre las más recomendadas?';
}

