function isPureGreeting(text) {
  const normalized = normalize(text);

  const greetings = [
    'hola', 'buenas', 'buenos dias', 'buen dia', 
    'buenas tardes', 'buenas noches', 'hey', 'hello', 
    'hi', 'que tal', 'qué tal'
  ];

  return greetings.includes(normalized);
}

function detectCatalogLookupMode({
  mode,
  userMessage,
  categoryCandidate,
  productCandidate,
  preference
}) {
  const text = normalize(userMessage);

  // 1. Saludo puro: no consultar catálogo todavía
  if (isPureGreeting(text)) {
    return {
      catalog_lookup_mode: 'none',
      reason: 'pure_greeting'
    };
  }

  // 2. Producto específico
  if (mode === 'product_detail' || productCandidate) {
    return {
      catalog_lookup_mode: 'product_detail',
      reason: 'specific_product_request'
    };
  }

  // 3. Búsqueda por categoría, necesidad o preferencia
  if (mode === 'recommendation' || categoryCandidate || preference) {
    return {
      catalog_lookup_mode: 'products',
      reason: 'category_or_need_search'
    };
  }

  // 4. Exploración general del catálogo
  const catalogSignals = [
    'que venden', 'qué venden', 'que productos', 'qué productos',
    'productos manejan', 'que manejan', 'qué manejan', 'catalogo',
    'catálogo', 'opciones', 'mostrar productos', 'ver productos',
    'que tienen', 'qué tienen'
  ];

  if (catalogSignals.some(signal => text.includes(normalize(signal)))) {
    return {
      catalog_lookup_mode: 'categories',
      reason: 'catalog_discovery_request'
    };
  }

  // 5. Mensaje general sin señal clara de catálogo
  return {
    catalog_lookup_mode: 'none',
    reason: 'general_message_without_catalog_signal'
  };
}

return items.map(item => {
  const m2Input = item.json.m2_input || item.json;

  const intent = $('Validate M2 Input').first().json.m2_input.decision.intent || 'general_inquiry';

  const modeByIntent = {
    general_inquiry: 'discovery',
    product_search: 'recommendation',
    product_specific: 'product_detail'
  };

  const mode = modeByIntent[intent] || 'discovery';

  const userMessage = $('Validate M2 Input').first().json.m2_input.input.text || '';
  const categoryCandidate = m2Input.extracted?.category_candidate || null;
  const preference = m2Input.extracted?.preference || null;

  // --- PASO 6: LÓGICA DE EXTRACCIÓN DE PRODUCTO CON MEMORIA ---
  const sessionMemory = m2Input.session_memory || {};
  const memoryFocusProduct = getFocusProductFromMemory(sessionMemory);

  let productCandidate = m2Input.extracted?.product_candidate || null;

  if (!productCandidate && sessionMemory.usable && memoryFocusProduct && m2Input.extracted?.memory_resolved) {
    productCandidate = memoryFocusProduct.display_name || null;
  }
  // ------------------------------------------------------------

  const retrieval = detectCatalogLookupMode({
    mode,
    userMessage,
    categoryCandidate,
    productCandidate,
    preference
  });

  // --- PASO 6: FORZAR BÚSQUEDA DE DETALLE SI HAY PRODUCTO ---
  if (productCandidate) {
    retrieval.catalog_lookup_mode = 'product_detail';
    retrieval.reason = 'specific_product_request_from_memory_or_input';
  }
  // ----------------------------------------------------------

  return {
    json: {
      ...item.json,
      advisor_request: {
        mode,
        user_message: userMessage,
        intent,
        commercial_stage: m2Input.decision?.commercial_stage || 'unknown',
        category_candidate: categoryCandidate,
        product_candidate: productCandidate,
        quantity: m2Input.extracted?.quantity || null,
        city: m2Input.extracted?.city || null,
        preference,
        retrieval,
        // --- PASO 6: PASAR MEMORIA AL SIGUIENTE NODO ---
        session_memory: sessionMemory
        // -----------------------------------------------
      }
    }
  };
});

