            product_id: sku,
            sku: sku,
            display_name: name,
            category: row.categoria || row.category || 'General',
            description_short: row.descripcion || row.description_short || '',
            price: parsePrice(row.precio || row.price),
            demo_active: true,
            retrieval_score: 10
        });
    }
});

// 3.2 Luego metemos/sobreescribimos con Qdrant (PISA a Google Sheets y le da score MÁXIMO)
qdrantItems.forEach(row => {
    const meta = (row.document && row.document.metadata) || row.metadata || {};
    const sku = meta.sku || meta.SKU || meta.product_id || 'UNKNOWN';
    const name = meta.titulo || meta.Titulo || meta.display_name || 'Sin nombre';

    if (name !== 'Sin nombre') {
        catalogMap.set(sku, {
            product_id: sku,
            sku: sku,
            display_name: name,
            category: meta.categoria || meta.category || 'General',
            description_short: meta.descripcion || meta.description || (row.document && row.document.pageContent) || '',
            price: parsePrice(meta.precio || meta.price || row.precio),
            stock_status: meta.stock_status || meta.estado || 'in_stock',
            demo_active: true,
            retrieval_score: 100, // PUNTAJE MÁXIMO
            retrieval_reasons: ['Encontrado directamente en Qdrant por búsqueda semántica']
        });
    }
});

// 4. Filtrar y ordenar los mejores resultados
const finalCatalogItems = Array.from(catalogMap.values())
    .sort((a, b) => b.retrieval_score - a.retrieval_score)
    .slice(0, 5); // Tomamos los 5 mejores

// 5. Devolver la estructura EXACTA que espera Build Advisor Context
return [
    {
        json: {
            ...$('Build Advisor Request').first().json,
            catalog_context: {
                source: 'hybrid_god_mode',
                lookup_mode: lookupMode,
                matched: finalCatalogItems.length > 0,
