function safeParse(value) {
  if (typeof value === 'object' && value !== null) return value;

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (e) {
      const match = value.match(/\{[\s\S]*\}/);
      if (match) {
        try {
          return JSON.parse(match[0]);
        } catch (_) {}
      }
    }
  }

  return {};
}

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function findProductById(productId) {
  const candidates = [
    ...(advisorContext.recommendation_candidates || []),
    ...(advisorContext.catalog_context?.items || []),
    ...(advisorContext.primary_product ? [advisorContext.primary_product] : [])
  ];

  return candidates.find(product =>
    normalize(product.product_id || product.sku) === normalize(productId)
  );
}

function findProductByName(name) {
  const candidates = [
    ...(advisorContext.recommendation_candidates || []),
    ...(advisorContext.catalog_context?.items || []),
    ...(advisorContext.primary_product ? [advisorContext.primary_product] : [])
  ];

  return candidates.find(product =>
    normalize(product.display_name) === normalize(name)
  );
}

function compactCatalogItem(item) {
  const productId = item.product_id || item.sku || null;
  const productFromContext = productId ? findProductById(productId) : null;
  const productFromName = item.display_name ? findProductByName(item.display_name) : null;

  const source = productFromContext || productFromName || item;

  return {
    product_id: source.product_id || source.sku || item.product_id || null,
    display_name: source.display_name || item.display_name || '',
    category: source.category || item.category || '',
    description_short: source.description_short || item.description_short || '',
    color: source.color || item.color || '',
    price: source.price ?? item.price ?? null,
    stock_status: source.stock_status || item.stock_status || null,
    image_ref: source.image_ref || item.image_ref || null
  };
}

